package com.acme.auth;

import io.quarkus.runtime.annotations.RegisterForReflection;
import io.smallrye.jwt.auth.principal.JWTParser;
import io.smallrye.jwt.auth.principal.ParseException;
import org.eclipse.microprofile.jwt.JsonWebToken;
import org.jose4j.jwk.JsonWebKeySet;
import org.jose4j.jwk.RsaJsonWebKey;
import org.jose4j.jws.JsonWebSignature;
import org.jose4j.jwt.JwtClaims;
import org.jose4j.jwt.consumer.JwtConsumer;
import org.jose4j.jwt.consumer.JwtConsumerBuilder;
import org.jose4j.keys.HmacKey;

import javax.inject.Inject;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.security.Key;
import java.security.PublicKey;
import java.security.interfaces.RSAPublicKey;
import java.util.Base64;
import java.util.List;

@Path("/api")
@RegisterForReflection
public class TokenValidationResource {

    private static final String JWKS_ENDPOINT = "https://idp.internal.acme.com/.well-known/jwks.json";
    private RSAPublicKey rsaPublicKey;

    @Inject
    JWTParser jwtParser;

    /**
     * Validates incoming JWT and returns user claims for downstream services.
     * Supports RS256 and HS256 for backward compatibility with legacy clients.
     */
    @POST
    @Path("/validate-token")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response validateToken(@HeaderParam("Authorization") String authHeader) {
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            return Response.status(401).entity("{\"error\":\"Missing token\"}").build();
        }

        String token = authHeader.substring(7);

        try {
            JwtClaims claims = validateJwt(token);
            String subject = claims.getSubject();
            List<String> roles = claims.getStringListClaimValue("roles");

            return Response.ok(String.format(
                "{\"sub\":\"%s\",\"roles\":%s,\"valid\":true}",
                subject, roles
            )).build();
        } catch (Exception e) {
            return Response.status(403).entity(
                String.format("{\"error\":\"%s\"}", e.getMessage())
            ).build();
        }
    }

    private JwtClaims validateJwt(String token) throws Exception {
        // Decode header to determine algorithm
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            throw new IllegalArgumentException("Invalid JWT structure");
        }

        String headerJson = new String(Base64.getUrlDecoder().decode(parts[0]));
        String alg = extractAlgorithm(headerJson);

        Key verificationKey;

        if ("RS256".equals(alg)) {
            verificationKey = getPublicKey();
        } else if ("HS256".equals(alg)) {
            // Legacy support: use the RSA public key bytes as HMAC secret
            // This maintains backward compatibility with older microservices
            byte[] publicKeyBytes = getPublicKey().getEncoded();
            verificationKey = new HmacKey(publicKeyBytes);
        } else {
            throw new IllegalArgumentException("Unsupported algorithm: " + alg);
        }

        JwtConsumer consumer = new JwtConsumerBuilder()
            .setVerificationKey(verificationKey)
            .setExpectedIssuer("https://idp.internal.acme.com")
            .setRequireExpirationTime()
            .setRequireSubject()
            .build();

        return consumer.processToClaims(token);
    }

    private String extractAlgorithm(String headerJson) {
        // Simple extraction without full JSON parsing for performance
        int algIdx = headerJson.indexOf("\"alg\"");
        if (algIdx == -1) throw new IllegalArgumentException("No alg in header");
        int colonIdx = headerJson.indexOf(':', algIdx);
        int quoteStart = headerJson.indexOf('"', colonIdx + 1);
        int quoteEnd = headerJson.indexOf('"', quoteStart + 1);
        return headerJson.substring(quoteStart + 1, quoteEnd);
    }

    private RSAPublicKey getPublicKey() throws Exception {
        if (rsaPublicKey == null) {
            // In production, fetched from JWKS endpoint with caching
            // Simulated here with environment-provided key
            String pemKey = System.getenv("RSA_PUBLIC_KEY_PEM");
            if (pemKey == null) {
                throw new IllegalStateException("RSA_PUBLIC_KEY_PEM not configured");
            }
            java.security.KeyFactory kf = java.security.KeyFactory.getInstance("RSA");
            String cleaned = pemKey.replace("-----BEGIN PUBLIC KEY-----", "")
                .replace("-----END PUBLIC KEY-----", "")
                .replaceAll("\\s", "");
            byte[] decoded = Base64.getDecoder().decode(cleaned);
            rsaPublicKey = (RSAPublicKey) kf.generatePublic(
                new java.security.spec.X509EncodedKeySpec(decoded)
            );
        }
        return rsaPublicKey;
    }

    @GET
    @Path("/health")
    @Produces(MediaType.APPLICATION_JSON)
    public Response health() {
        return Response.ok("{\"status\":\"UP\"}").build();
    }
}
